"""Phase 4.2A remote surfaces: genuine local HTTP, paired commands; no device claims."""
from test_command_bridge import CommandBridge
class ObservationRemote(CommandBridge):
 def test_observation_remote_array_lighting_and_legacy_budget(self):
  pc=self.page(pc=True);pc.wait_for_function('document.querySelector("#rd-bridge-status").textContent.includes("LINKED")');phone=self.page(width=390,height=844);self.tab(phone,'icarus');phone.wait_for_selector('.obs-preview');self.assertEqual(phone.locator('.obs-preview').count(),4);self.assertFalse(any('Crew Quarters' in label for label in phone.locator('.obs-select option').all_text_contents()));self.assertNotIn('observation',self.m.ICARUS_BRIDGE['telemetry']);self.assertIn('observation',self.m.BRIDGE_SERVICE.data)
  phone.locator('.ship-schematic [data-room="C05"]').click();phone.locator('.ship-schematic .schematic-detail select').select_option('0.5');pc.wait_for_function('__icarusSoak.snapshot().roomLighting?.C05===0.5');self.assertEqual(pc.evaluate('__icarusSoak.time()'),0);self.assertEqual(phone.evaluate('typeof __icarusSoak'),'undefined');self.assertLessEqual(phone.evaluate('document.documentElement.scrollWidth'),392)
  status,d=self.req('/api/icarus/dispatch',{'command':'room:light:C05:0.25','requestId':'observation-dedup'},{'Authorization':'Bearer test-client'});status,e=self.req('/api/icarus/dispatch',{'command':'room:light:C05:0.25','requestId':'observation-dedup'},{'Authorization':'Bearer test-client'});self.assertEqual(d['queued'],e['queued']);pc.wait_for_function('__icarusSoak.snapshot().roomLighting.C05===0.25');self.assertEqual(pc.evaluate('__icarusSoak.snapshot().resourceAudit'),[])
